import { RandomState } from '@studio/engine/random/random-state';
import { decodeParams } from '../params';
import reference from '../testing/reference-puzzles.json';
import { generateRectangles } from './generate';

/**
 * The reference puzzles were generated by the original C code (see
 * tools/c-reference). The port must reproduce every one exactly.
 */
describe('generateRectangles matches the original C generator', () => {
  for (const ref of reference) {
    it(`${ref.params}#${ref.seed}`, () => {
      const puzzle = generateRectangles(decodeParams(ref.params), new RandomState(ref.seed));
      expect(puzzle.description).toBe(ref.description);
      expect(puzzle.solution).toBe(ref.solution);
    });
  }
});
